fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    assert!(!v.is_empty());
    assert!(end < v.len());

    let mut best_val = v[0];
    let mut best_idx = 0usize;

    for i in 1..=end {
        if v[i] > best_val {
            best_val = v[i];
            best_idx = i;
        }
    }
    (best_val, best_idx)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    assert!(!v.is_empty());
    assert!(start < v.len());

    let mut best_val = v[start];
    let mut best_idx = start;

    for i in (start + 1)..v.len() {
        if v[i] < best_val {
            best_val = v[i];
            best_idx = i;
        }
    }
    (best_val, best_idx)
}

fn barrier(v: &[i32], p: usize) -> bool {
    assert!(!v.is_empty());
    assert!(p < v.len());

    // Vacuously true if there is no element to the right.
    if p + 1 >= v.len() {
        return true;
    }

    let (max_left, _) = find_max_in_prefix(v, p);
    let (min_right, _) = find_min_in_suffix(v, p + 1);
    max_left < min_right
}